// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract MockERC20 is ERC20 {
    uint8 private _customDecimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _customDecimals = decimals_;
    }

    function decimals() public view virtual override returns (uint8) {
        return _customDecimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

contracts/StakingPlatform.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title Staking Platform (Factory + Pool)
/// @notice Factory deploys staking pools where users can stake a token and earn APR rewards
///         calculated per-second. Modeled similarly to VestingSalePlatform pattern.
contract StakingPlatform is Ownable(msg.sender) {
    using SafeERC20 for IERC20;

    uint256 public constant BPS_DENOM = 10_000; // 100% = 10000

    /// @notice Pool creation fee in BNB (default 0.002 BNB)
    uint256 public poolCreationFee = 0.002 ether;

    /// @notice Treasury where pool creation fees are sent
    address public treasury;

    /// @notice Basic pool metadata stored in factory for discovery
    struct PoolMeta {
        address poolAddress;
        address owner; // project owner who created pool
        address stakingToken;
        address rewardToken; // if zero at creation, equals stakingToken in child
        uint256 aprBps; // APR in basis points (e.g. 500 = 5% APR)
        uint256 createdAt;
        uint256 duration; // pool duration in seconds
        uint256 endTime; // createdAt + duration
        bool active; // mirrored from child; owner may pause/close new rewards
        uint256 totalStaked; // mirrored from child
        uint256 totalClaimed; // mirrored from child
    }

    // Pools registry
    mapping(uint256 => PoolMeta) public pools; // poolId => meta
    uint256 public totalPoolsCount;
    mapping(address => uint256) public poolIdOf; // child => id

    // Owner index
    mapping(address => uint256[]) private _ownerPoolIds; // owner => ids

    // User stake tracking
    mapping(address => uint256[]) private _userActivePools; // user => poolIds where user has active stake
    mapping(address => mapping(uint256 => bool)) private _userInPool; // user => poolId => hasStake

    // Emergency withdrawal timelock
    mapping(uint256 => uint256) public emergencyTimestamp; // poolId => timestamp when emergency triggered
    uint256 public constant EMERGENCY_DELAY = 24 hours; // 24 hour delay for emergency withdrawal

    /// @notice Emitted when a new pool is created
    event PoolCreated(
        uint256 indexed poolId,
        address indexed poolAddress,
        address indexed owner,
        address stakingToken,
        address rewardToken,
        uint256 aprBps,
        uint256 duration,
        uint256 endTime
    );

    /// @notice Emitted when pool state mirrors change
    event PoolMirrored(uint256 indexed poolId, uint256 totalStaked, uint256 totalClaimed, bool active);

    /// @notice Emitted when emergency withdrawal is initiated
    event EmergencyInitiated(uint256 indexed poolId, uint256 executeAfter);

    /// @notice Emitted when emergency withdrawal is executed
    event EmergencyExecuted(uint256 indexed poolId);

    /// @notice Emitted when emergency withdrawal is cancelled
    event EmergencyCancelled(uint256 indexed poolId);

    /// @notice Emitted when pool creation fee is changed
    event PoolCreationFeeSet(uint256 newFee);

    /// @notice Emitted when treasury is changed
    event TreasuryChanged(address indexed oldTreasury, address indexed newTreasury);

    /// @notice Emitted when pool creation fee is collected
    event FeeCollected(address indexed payer, uint256 amount);

    // --------- Constructor ---------

    constructor(address _treasury) {
        treasury = _treasury == address(0) ? msg.sender : _treasury;
    }

    // --------- Views ---------

    function totalPools() external view returns (uint256) {
        return totalPoolsCount;
    }

    function getPoolsInRange(uint256 fromId, uint256 toId) external view returns (PoolMeta[] memory list) {
        require(toId >= fromId, "range");
        require(toId <= totalPoolsCount, "oob");
        uint256 len = toId - fromId + 1;
        list = new PoolMeta[](len);
        for (uint256 i = 0; i < len; i++) {
            list[i] = pools[fromId + i];
        }
    }

    function getPoolByIndex(uint256 poolId) external view returns (PoolMeta memory) {
        return pools[poolId];
    }

    function getOwnerPoolIds(address owner_) external view returns (uint256[] memory) {
        return _ownerPoolIds[owner_];
    }

    /// @notice Returns pool IDs where user has active stakes
    /// @param user The user address to check
    /// @return Array of pool IDs where user has active stakes
    function getUserActivePools(address user) external view returns (uint256[] memory) {
        return _userActivePools[user];
    }

    /// @notice Returns the current pool creation fee
    /// @return The fee amount in BNB wei
    function getPoolCreationFee() external view returns (uint256) {
        return poolCreationFee;
    }

    // --------- Hooks from child to mirror lightweight stats ---------

    function _mirror(uint256 totalStaked, uint256 totalClaimed, bool active) external {
        uint256 id = poolIdOf[msg.sender];
        // Verify that msg.sender is actually a registered pool
        require(pools[id].poolAddress == msg.sender, "pool");
        PoolMeta storage m = pools[id];
        m.totalStaked = totalStaked;
        m.totalClaimed = totalClaimed;
        m.active = active;
        emit PoolMirrored(id, totalStaked, totalClaimed, active);
    }

    /// @notice Add user to pool's active list (called by child pool)
    /// @dev Only pool contracts can call this
    /// @param user The user who staked
    function _addUserToPool(address user) external {
        uint256 poolId = poolIdOf[msg.sender];
        // Verify that msg.sender is actually a registered pool
        require(pools[poolId].poolAddress == msg.sender, "pool");

        // If user is not already in this pool, add them
        if (!_userInPool[user][poolId]) {
            _userActivePools[user].push(poolId);
            _userInPool[user][poolId] = true;
        }
    }

    /// @notice Remove user from pool's active list (called by child pool)
    /// @dev Only pool contracts can call this
    /// @param user The user who unstaked completely
    function _removeUserFromPool(address user) external {
        uint256 poolId = poolIdOf[msg.sender];
        // Verify that msg.sender is actually a registered pool
        require(pools[poolId].poolAddress == msg.sender, "pool");

        // If user is in this pool, remove them
        if (_userInPool[user][poolId]) {
            // Remove from active pools array
            uint256[] storage userPools = _userActivePools[user];
            for (uint256 i = 0; i < userPools.length; i++) {
                if (userPools[i] == poolId) {
                    userPools[i] = userPools[userPools.length - 1];
                    userPools.pop();
                    break;
                }
            }
            _userInPool[user][poolId] = false;
        }
    }

    // --------- Admin functions ---------

    /// @notice Set treasury address (only owner)
    /// @param _treasury New treasury address
    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "treasury=0");
        emit TreasuryChanged(treasury, _treasury);
        treasury = _treasury;
    }

    /// @notice Set pool creation fee (only owner)
    /// @param newFee New fee amount in BNB wei
    function setPoolCreationFee(uint256 newFee) external onlyOwner {
        poolCreationFee = newFee;
        emit PoolCreationFeeSet(newFee);
    }

    // --------- Create pool ---------

    function createPool(
        address stakingToken,
        uint256 aprBps,
        uint256 duration,
        uint256 initialRewardAmount
    ) external payable returns (uint256 poolId, address poolAddress) {
        require(msg.value >= poolCreationFee, "insufficient-fee");
        require(stakingToken != address(0), "stake=0");
        require(duration >= 1 days && duration <= 365 days, "duration");
        require(initialRewardAmount > 0, "no-rewards");
        require(aprBps <= BPS_DENOM * 5, "apr-high"); // cap APR <= 500% to avoid obvious mistakes

        // Emit fee collection event
        emit FeeCollected(msg.sender, msg.value);

        uint256 endTime = block.timestamp + duration;
        StakingPool pool = new StakingPool(
            address(this),
            msg.sender,
            stakingToken,
            aprBps,
            endTime
        );

        PoolMeta memory meta = PoolMeta({
            poolAddress: address(pool),
            owner: msg.sender,
            stakingToken: stakingToken,
            rewardToken: stakingToken, // reward token same as staking token
            aprBps: aprBps,
            createdAt: block.timestamp,
            duration: duration,
            endTime: endTime,
            active: true,
            totalStaked: 0,
            totalClaimed: 0
        });

        totalPoolsCount += 1;
        poolId = totalPoolsCount;
        pools[poolId] = meta;
        poolIdOf[address(pool)] = poolId;
        _ownerPoolIds[msg.sender].push(poolId);

        // Transfer initial reward tokens from creator to pool contract
        IERC20(stakingToken).safeTransferFrom(msg.sender, address(pool), initialRewardAmount);

        // Initialize reward reserve in pool contract
        StakingPool(address(pool)).initializeRewards(initialRewardAmount);

        emit PoolCreated(poolId, address(pool), msg.sender, stakingToken, stakingToken, aprBps, duration, endTime);

        // Forward creation fee to treasury
        if (msg.value > 0) {
            (bool ok, ) = payable(treasury).call{value: msg.value}("");
            require(ok, "fee-xfer");
        }

        return (poolId, address(pool));
    }

    /// @notice Initiate emergency withdrawal - starts 24 hour timelock
    /// @dev Only factory owner can trigger emergency withdrawal
    /// @param poolId The ID of the pool to prepare for emergency withdrawal
    function initiateEmergencyWithdraw(uint256 poolId) external onlyOwner {
        require(poolId > 0 && poolId <= totalPoolsCount, "invalid-pool");
        require(emergencyTimestamp[poolId] == 0, "already-initiated");

        emergencyTimestamp[poolId] = block.timestamp;
        emit EmergencyInitiated(poolId, block.timestamp + EMERGENCY_DELAY);
    }

    /// @notice Execute emergency withdrawal after timelock period
    /// @dev Can only be called after 24 hour delay
    /// @param poolId The ID of the pool to withdraw from
    function executeEmergencyWithdraw(uint256 poolId) external onlyOwner {
        require(poolId > 0 && poolId <= totalPoolsCount, "invalid-pool");
        require(emergencyTimestamp[poolId] > 0, "not-initiated");
        require(block.timestamp >= emergencyTimestamp[poolId] + EMERGENCY_DELAY, "timelock-active");

        PoolMeta storage meta = pools[poolId];
        address poolAddress = meta.poolAddress;
        require(poolAddress != address(0), "pool-not-exist");

        // Reset emergency timestamp
        emergencyTimestamp[poolId] = 0;

        // Call emergency withdraw on the pool contract
        StakingPool(poolAddress).emergencyWithdraw();

        emit EmergencyExecuted(poolId);
    }

    /// @notice Cancel emergency withdrawal before execution
    /// @dev Only factory owner can cancel
    /// @param poolId The ID of the pool to cancel emergency withdrawal for
    function cancelEmergencyWithdraw(uint256 poolId) external onlyOwner {
        require(poolId > 0 && poolId <= totalPoolsCount, "invalid-pool");
        require(emergencyTimestamp[poolId] > 0, "not-initiated");

        emergencyTimestamp[poolId] = 0;
        emit EmergencyCancelled(poolId);
    }
}

/// @dev Child staking pool with per-second APR rewards
contract StakingPool is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 private constant BPS_DENOM = 10_000;
    uint256 private constant YEAR = 365 days;

    StakingPlatform public immutable factory;
    address public immutable owner; // project owner
    address public immutable stakingToken;
    address public immutable rewardToken; // equals stakingToken if set to 0 at creation
    uint256 public immutable endTime; // pool automatically deactivates after this time
    uint8 public immutable stakingDecimals; // staking token decimals (6, 9, 18, etc.)
    uint8 public immutable rewardDecimals; // reward token decimals
    uint256 public aprBps; // APR in basis points
    bool public active; // if false, no new stake and rewards stop accruing from setActive(false) time

    // Pool aggregates
    uint256 public totalStaked;
    uint256 public totalClaimed;
    uint256 public rewardReserve; // dedicated reward token reserve

    struct UserInfo {
        uint256 amount;        // staked amount
        uint256 pending;       // accumulated but not yet claimed rewards
        uint256 claimed;       // lifetime claimed rewards
        uint256 lastUpdate;    // timestamp of last reward update/claim/stake change
    }
    mapping(address => UserInfo) public users;

    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event Claimed(address indexed user, uint256 amount);
    event Funded(address indexed from, uint256 amount);
    event ActiveSet(bool active);
    event AprSet(uint256 aprBps);

    modifier onlyOwner() {
        require(msg.sender == owner, "owner");
        _;
    }

    constructor(
        address _factory,
        address _owner,
        address _stakingToken,
        uint256 _aprBps,
        uint256 _endTime
    ) {
        require(_factory != address(0) && _owner != address(0) && _stakingToken != address(0), "zero");
        require(_endTime > block.timestamp, "endTime");
        factory = StakingPlatform(_factory);
        owner = _owner;
        stakingToken = _stakingToken;
        rewardToken = _stakingToken; // reward token is same as staking token
        endTime = _endTime;

        // Get token decimals (both same since same token)
        stakingDecimals = IERC20Metadata(_stakingToken).decimals();
        rewardDecimals = stakingDecimals; // same as staking decimals

        require(_aprBps <= BPS_DENOM * 5, "apr-high");
        aprBps = _aprBps;
        active = true;
    }

    /// @notice Initialize reward reserve (called only once by factory during pool creation)
    function initializeRewards(uint256 amount) external {
        require(msg.sender == address(factory), "only-factory");
        require(rewardReserve == 0, "already-init");
        rewardReserve = amount;
        emit Funded(tx.origin, amount);
    }

    // --------- Admin ---------

    function setActive(bool _active) external onlyOwner {
        active = _active;
        _updateMirror();
        emit ActiveSet(_active);
    }

    function setAprBps(uint256 _aprBps) external onlyOwner {
        require(_aprBps <= BPS_DENOM * 5, "apr-high");
        aprBps = _aprBps;
        _updateMirror();
        emit AprSet(_aprBps);
    }

    /// @notice Fund reward reserves with rewardToken
    function fundRewards(uint256 amount) external onlyOwner {
        require(amount > 0, "zero");
        IERC20(rewardToken).safeTransferFrom(msg.sender, address(this), amount);
        rewardReserve += amount;
        emit Funded(msg.sender, amount);
    }

    /// @notice Emergency withdrawal - only factory owner can withdraw all tokens
    /// @dev This is for emergency situations only
    function emergencyWithdraw() external {
        require(msg.sender == address(factory), "only-factory");

        // Prevent multiple emergency withdrawals
        require(active, "already-emergency");

        // Get total balance of the staking token in this contract
        uint256 balance = IERC20(stakingToken).balanceOf(address(this));

        if (balance > 0) {
            // Only withdraw excess tokens above totalStaked + rewardReserve
            // This protects user staked funds and allocated rewards
            uint256 protectedAmount = totalStaked + rewardReserve;

            if (balance > protectedAmount) {
                uint256 excessAmount = balance - protectedAmount;
                IERC20(stakingToken).safeTransfer(StakingPlatform(factory).owner(), excessAmount);
            }
        }

        // Clear reward reserve and deactivate pool
        // Keep totalStaked intact to protect user funds
        rewardReserve = 0;
        active = false;

        // Update mirror to reflect emergency state consistently
        _updateMirror();

        emit ActiveSet(false);
    }

    // --------- Core: staking, unstaking, claiming ---------

    function stake(uint256 amount) external nonReentrant {
        _checkExpiration(); // Auto-deactivate if expired only
        require(active, "inactive");
        require(amount > 0, "zero");
        _accrue(msg.sender);
        users[msg.sender].amount += amount;
        totalStaked += amount;
        IERC20(stakingToken).safeTransferFrom(msg.sender, address(this), amount);

        // Notify factory about user staking (if first time in this pool)
        factory._addUserToPool(msg.sender);

        _updateMirror();
        emit Staked(msg.sender, amount);
    }

    function unstake() external nonReentrant {
        UserInfo storage u = users[msg.sender];
        require(u.amount > 0, "no-stake");

        // First accrue any pending rewards
        _accrue(msg.sender);

        uint256 stakeAmount = u.amount;
        uint256 claimableAmount = u.pending;

        // Reset user state
        u.amount = 0;
        u.pending = 0;
        if (claimableAmount > 0) {
            u.claimed += claimableAmount;
        }

        // Update pool totals
        totalStaked -= stakeAmount;
        if (claimableAmount > 0) {
            totalClaimed += claimableAmount;
            // Note: rewardReserve was already deducted during _accrue()
        }

        // Notify factory about user completely unstaking BEFORE external calls
        factory._removeUserFromPool(msg.sender);

        // Update mirror BEFORE external calls
        _updateMirror();

        // Transfer staked tokens back to user
        IERC20(stakingToken).safeTransfer(msg.sender, stakeAmount);

        // Transfer claimable rewards if any
        if (claimableAmount > 0) {
            IERC20(rewardToken).safeTransfer(msg.sender, claimableAmount);
            emit Claimed(msg.sender, claimableAmount);
        }
        emit Unstaked(msg.sender, stakeAmount);
    }

    function claim() external nonReentrant {
        _accrue(msg.sender); // Accrue rewards first, before checking expiration
        _checkAndUpdateActive(); // Auto-deactivate if expired or no rewards
        uint256 amt = users[msg.sender].pending;
        require(amt > 0, "no-claim");

        // Rewards are pre-allocated during accrual, so pending amount should always be claimable

        users[msg.sender].pending = 0;
        users[msg.sender].claimed += amt;
        totalClaimed += amt;
        // Note: rewardReserve was already deducted during _accrue()
        IERC20(rewardToken).safeTransfer(msg.sender, amt);
        _updateMirror();
        emit Claimed(msg.sender, amt);
    }

    // --------- Internals ---------

    function _accrue(address user) internal {
        UserInfo storage u = users[user];
        uint256 last = u.lastUpdate;
        uint256 nowTs = block.timestamp;
        if (last == 0) {
            u.lastUpdate = nowTs;
            return;
        }
        if (!active) {
            // When pool inactive, do not accrue beyond lastUpdate
            u.lastUpdate = nowTs; // still advance marker to avoid reprocessing past periods
            return;
        }
        if (u.amount == 0) {
            u.lastUpdate = nowTs;
            return;
        }
        uint256 dt = nowTs - last;
        if (dt == 0) return;
        // Cap accrual at endTime
        uint256 accrueUntil = nowTs > endTime ? endTime : nowTs;
        if (accrueUntil <= last) return;
        dt = accrueUntil - last;
        // reward = amount * apr% * dt / YEAR
        // Since staking and reward tokens are the same, no normalization needed
        // Use safe math to prevent overflow: (amount * aprBps * dt) / (BPS_DENOM * YEAR)
        uint256 reward = (u.amount * aprBps * dt) / (BPS_DENOM * YEAR);

        // Atomic operation to prevent race conditions in reward allocation
        if (rewardReserve >= reward) {
            u.pending += reward;
            rewardReserve -= reward; // Deduct from reserve as we allocate
        } else {
            // If insufficient reserves, allocate only what's available
            if (rewardReserve > 0) {
                u.pending += rewardReserve;
                rewardReserve = 0; // Use all remaining reserves
            }
        }

        u.lastUpdate = nowTs;
    }

    function _checkExpiration() internal {
        if (!active) return; // already inactive

        // Check if pool expired
        if (block.timestamp >= endTime) {
            active = false;
            emit ActiveSet(false);
        }
    }

    function _checkAndUpdateActive() internal {
        if (!active) return; // already inactive

        // Check if pool expired
        if (block.timestamp >= endTime) {
            active = false;
            emit ActiveSet(false);
        }
    }



    function _hasRewardReserves(uint256 amount) internal view returns (bool) {
        return rewardReserve >= amount;
    }

    function _updateMirror() internal {
        factory._mirror(totalStaked, totalClaimed, active);
    }

    // --------- Views ---------

    /// @notice Returns user's current stake data and live claimable reward
    function getUserStake(address user) external view returns (
        uint256 amount,
        uint256 claimable,
        uint256 claimed,
        uint256 lastClaimTs
    ) {
        UserInfo memory u = users[user];
        amount = u.amount;
        claimed = u.claimed;
        lastClaimTs = u.lastUpdate;
        // simulate accrue
        if (u.lastUpdate == 0 || u.amount == 0 || !active) {
            return (amount, u.pending, claimed, lastClaimTs);
        }
        uint256 accrueUntil = block.timestamp > endTime ? endTime : block.timestamp;
        if (accrueUntil <= u.lastUpdate) {
            return (amount, u.pending, claimed, lastClaimTs);
        }
        uint256 dt = accrueUntil - u.lastUpdate;
        // Since staking and reward tokens are the same, no normalization needed
        // Use safe math to prevent overflow: (amount * aprBps * dt) / (BPS_DENOM * YEAR)
        uint256 reward = (u.amount * aprBps * dt) / (BPS_DENOM * YEAR);
        claimable = u.pending + reward;
        return (amount, claimable, claimed, lastClaimTs);
    }

    /// @notice Detailed reward allocation analysis
    /// @return totalAllocated Total rewards initially allocated to pool
    /// @return totalDistributed Total rewards distributed to users  
    /// @return remainingRewards Remaining rewards in reserve
    /// @return distributedPercentage Percentage of rewards distributed (in basis points)
    /// @return remainingPercentage Percentage of rewards remaining (in basis points)
    function getRewardAnalysis() external view returns (
        uint256 totalAllocated,
        uint256 totalDistributed,
        uint256 remainingRewards,
        uint256 distributedPercentage,
        uint256 remainingPercentage
    ) {
        // Note: "totalAllocated" here represents claimed + remaining reserves.
        // It intentionally excludes rewards allocated to users' pending balances
        // (which have already been deducted from reserves during accrual).
        totalDistributed = totalClaimed;
        remainingRewards = rewardReserve;
        totalAllocated = totalDistributed + remainingRewards;

        if (totalAllocated == 0) {
            distributedPercentage = 0;
            remainingPercentage = 0;
        } else {
            // Calculate percentages in basis points (10000 = 100%)
            distributedPercentage = (totalDistributed * 10000) / totalAllocated;
            remainingPercentage = (remainingRewards * 10000) / totalAllocated;
        }

        return (totalAllocated, totalDistributed, remainingRewards, distributedPercentage, remainingPercentage);
    }

    /// @notice Convenience pool stats for UI
    function getPoolStats() external view returns (
        address _stakingToken,
        address _rewardToken,
        uint8 _stakingDecimals,
        uint8 _rewardDecimals,
        uint256 _aprBps,
        bool _active,
        uint256 _totalStaked,
        uint256 _totalClaimed,
        uint256 _rewardReserve,
        uint256 _endTime,
        bool _expired
    ) {
        _stakingToken = stakingToken;
        _rewardToken = rewardToken;
        _stakingDecimals = stakingDecimals;
        _rewardDecimals = rewardDecimals;
        _aprBps = aprBps;
        _active = active;
        _totalStaked = totalStaked;
        _totalClaimed = totalClaimed;
        _rewardReserve = rewardReserve;
        _endTime = endTime;
        _expired = block.timestamp >= endTime;
    }
}

contracts/VestingSalePlatform.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/// @notice Payment currency enum
enum PaymentCurrency {
	NATIVE, // ETH
	USDT,
	USD1
}

/// @notice Purchase info shape required by the spec (referenced by child and factory)
struct PurchaseInfo {
	address saleAddress; // which sale
	uint256 amount;      // total bought tokens (1eTokenDecimals)
	uint256 claimed;     // already claimed (1eTokenDecimals)
	bool participated;   // used for buyersCount accounting
}

/// @title Vesting Sale Platform (Factory)
/// @notice A factory that deploys sale contracts which sell an ERC20 token for ETH or a whitelisted
///         stable (USDT / USD1) with linear (daily) vesting starting when the sale ends.
contract VestingSalePlatform is Ownable(msg.sender), ReentrancyGuard {
	using SafeERC20 for IERC20;
	using ECDSA for bytes32;
	using MessageHashUtils for bytes32;

	// -----------------------
	// Platform configuration
	// -----------------------

	/// @notice 1% platform fee taken from total proceeds on withdrawal (100 = 1%)
	uint256 public constant FEE_BPS = 100; // 100 bps = 1%
	uint256 public constant BPS_DENOM = 10_000;

	/// @notice Fee to create a sale (in wei) - can be updated by owner
	uint256 public saleCreationFee = 0.002 ether;

	/// @notice Default sale duration applied at creation (can be updated for future sales)
	uint256 public defaultSaleDuration = 180 days; // 6 months

	/// @notice Treasury where platform fee and creation fee are sent
	address public treasury;

	/// @notice Address whose signature authorizes purchases (off-chain pricing/quote)
	address public quoteSigner;

	/// @notice Whitelisted payment tokens
	address public usdt; // optional, can be zero if unused
	address public usd1; // optional, can be zero if unused

	/// @notice Basic sale metadata kept in the factory for discovery and listing
	struct Sale {
		address saleAddress;    // deployed sale contract address
		address projectOwner;   // seller address
		address token;          // token being sold
		PaymentCurrency currency; // payment currency type
		uint256 startTime;      // block.timestamp at creation
		uint256 endTime;        // startTime + duration unless ends early
		uint256 vestingDuration;// seconds
		uint256 hardCap;      // hard cap in token units (1eTokenDecimals)
		uint256 discount;       // discount percentage (basis points, e.g., 500 = 5%)
		uint256 soldTokens;     // updated by child
		uint256 buyersCount;    // updated by child
		bool endedEarly;        // true if finalized due to hard cap reached
	}

	/// @notice Emitted when a new sale is created
	event SaleCreated(
		uint256 indexed saleId,
		address indexed saleAddress,
		address indexed projectOwner,
		address token,
		PaymentCurrency currency,
		uint256 hardCap,
		uint256 discount,
		uint256 startTime,
		uint256 endTime,
		uint256 vestingDuration,
		bytes signature
	);

	/// @notice Emitted when treasury updated
	event TreasuryChanged(address indexed oldTreasury, address indexed newTreasury);

	/// @notice Emitted when default sale duration updated
	event DefaultSaleDurationChanged(uint256 oldDuration, uint256 newDuration);

	/// @notice Emitted when sale creation fee updated
	event SaleCreationFeeChanged(uint256 oldFee, uint256 newFee);

	/// @notice Emitted when quote signer updated
	event QuoteSignerChanged(address indexed oldSigner, address indexed newSigner);

	/// @notice Emitted on purchase (relayed by child)
	event Purchased(uint256 indexed saleId, address indexed buyer, uint256 paymentAmount, uint256 tokenAmount);

	/// @notice Emitted when buyer claims (relayed by child)
	event Claimed(uint256 indexed saleId, address indexed buyer, uint256 claimedAmount);

	/// @notice Emitted when project withdraws proceeds
	event ProceedsWithdrawn(uint256 indexed saleId, address indexed projectOwner, uint256 amountAfterFee, uint256 fee);

	/// @notice Emitted on emergency withdraw by platform owner
	event EmergencyWithdrawn(uint256 indexed saleId, address indexed token, address indexed to, uint256 amount);

	// -----------------------
	// Storage
	// -----------------------

	/// @notice Sales stored in a mapping by id
	mapping(uint256 => Sale) public sales; // saleId => Sale

	/// @notice Total number of sales created
	uint256 public totalSalesCount;

	/// @notice For quick lookup: sale address to saleId
	mapping(address => uint256) public saleIdOf;

	/// @notice User participation list: user => saleIds
	mapping(address => uint256[]) private _userSaleIds;

	constructor(address _treasury, address _usdt, address _usd1) {
		treasury = _treasury == address(0) ? msg.sender : _treasury;
		usdt = _usdt;
		usd1 = _usd1;
	}

	// -----------------------
	// Admin
	// -----------------------

	function setTreasury(address _treasury) external onlyOwner {
		require(_treasury != address(0), "treasury=0");
		emit TreasuryChanged(treasury, _treasury);
		treasury = _treasury;
	}

	/// @notice Update default sale duration for future sales
	function setDefaultSaleDuration(uint256 newDuration) external onlyOwner {
		require(newDuration >= 1 days && newDuration <= 365 days, "duration-range");
		emit DefaultSaleDurationChanged(defaultSaleDuration, newDuration);
		defaultSaleDuration = newDuration;
	}

	/// @notice Update sale creation fee
	function setSaleCreationFee(uint256 newFee) external onlyOwner {
		require(newFee <= 1 ether, "fee-too-high"); // Max 1 ETH to prevent mistakes
		emit SaleCreationFeeChanged(saleCreationFee, newFee);
		saleCreationFee = newFee;
	}

	function setPaymentTokenAddresses(address _usdt, address _usd1) external onlyOwner {
		usdt = _usdt;
		usd1 = _usd1;
	}

	function setQuoteSigner(address _signer) external onlyOwner {
		require(_signer != address(0), "signer=0");
		emit QuoteSignerChanged(quoteSigner, _signer);
		quoteSigner = _signer;
	}

	/// @notice Create a new sale, requiring a backend validation signature that attests
	///         the token/currency pair has valid liquidity at the time of signing.
	/// @dev The signature is produced off-chain by quoteSigner as:
	///      keccak256(abi.encode(chainId, token, currency, projectOwner, deadline))
	///      and signed via eth_sign (Ethereum Signed Message prefix).
	///      Including projectOwner (msg.sender) prevents signature reuse by others.
	function createSaleValidated(
		address token,
		PaymentCurrency currency,
		uint256 vestingDuration,
		uint256 hardCap,
		uint256 discount,
		uint256 deadline,
		bytes calldata signature
	) external payable nonReentrant returns (uint256 saleId, address saleAddress) {
		require(block.timestamp <= deadline, "expired");
		address signer = quoteSigner;
		require(signer != address(0), "no-signer");

		bytes32 digest = keccak256(
			abi.encode(
				block.chainid,
				token,
				currency,
				msg.sender,
				deadline
			)
		).toEthSignedMessageHash();
		require(digest.recover(signature) == signer, "sig");

		// Reuse the same validations and creation flow as createSale
		require(msg.value == saleCreationFee, "fee");
		require(token != address(0), "token=0");
		require(vestingDuration >= 1 days, "vesting");
		require(hardCap > 0, "hardCap");
		require(discount <= 10_000, "discount");
		if (currency == PaymentCurrency.USDT) require(usdt != address(0), "usdt=0");
		if (currency == PaymentCurrency.USD1) require(usd1 != address(0), "usd1=0");

		VestingSale child = new VestingSale(
			address(this),
			msg.sender,
			token,
			currency,
			block.timestamp,
			block.timestamp + defaultSaleDuration,
			vestingDuration,
			hardCap,
			discount
		);

		IERC20(token).safeTransferFrom(msg.sender, address(child), hardCap);

		Sale memory meta = Sale({
			saleAddress: address(child),
			projectOwner: msg.sender,
			token: token,
			currency: currency,
			startTime: block.timestamp,
			endTime: block.timestamp + defaultSaleDuration,
			vestingDuration: vestingDuration,
			hardCap: hardCap,
			discount: discount,
			soldTokens: 0,
			buyersCount: 0,
			endedEarly: false
		});

		totalSalesCount += 1;
		saleId = totalSalesCount;
		sales[saleId] = meta;
		saleIdOf[address(child)] = saleId;

		emit SaleCreated(
			saleId,
			address(child),
			msg.sender,
			token,
			currency,
			hardCap,
			discount,
			meta.startTime,
			meta.endTime,
			vestingDuration,
			signature
		);

		(bool ok, ) = payable(treasury).call{value: msg.value}("");
		require(ok, "fee-xfer");

		return (saleId, address(child));
	}

	// -----------------------
	// Child hooks (called by sales)
	// -----------------------

	/// @notice Called by child sale on each purchase to update platform indexes
	function onPurchase(address buyer, uint256 tokenAmount, uint256 paymentAmount) external {
		uint256 id = saleIdOf[msg.sender];
		require(sales[id].saleAddress == msg.sender, "sale");

		Sale storage m = sales[id];
		// update sold
		m.soldTokens += tokenAmount;

		emit Purchased(id, buyer, paymentAmount, tokenAmount);
	}

	/// @notice Called by child only on the first participation of a buyer
	function onFirstParticipation() external {
		uint256 id = saleIdOf[msg.sender];
		require(sales[id].saleAddress == msg.sender, "sale");
		Sale storage m = sales[id];
		m.buyersCount += 1;
	}

	/// @notice Called by child when sale ends early due to hard cap reached
	function onEndedEarly() external {
		uint256 id = saleIdOf[msg.sender];
		require(sales[id].saleAddress == msg.sender, "sale");
		sales[id].endedEarly = true;
		sales[id].endTime = block.timestamp;
	}

	/// @notice Called by child on claim to bubble up event
	function onClaim(address buyer, uint256 amount) external {
		uint256 id = saleIdOf[msg.sender];
		require(sales[id].saleAddress == msg.sender, "sale");
		emit Claimed(id, buyer, amount);
	}

	/// @notice Called by child when proceeds withdrawn by project owner
	function onProceedsWithdraw(uint256 amountAfterFee, uint256 fee) external {
		uint256 id = saleIdOf[msg.sender];
		require(sales[id].saleAddress == msg.sender, "sale");
		emit ProceedsWithdrawn(id, sales[id].projectOwner, amountAfterFee, fee);
	}

	// -----------------------
	// Views (as requested)
	// -----------------------

	/// @notice Get current sale creation fee
	function getSaleCreationFee() external view returns (uint256) {
		return saleCreationFee;
	}

	/// @notice Return total sales count
	function totalSales() external view returns (uint256) {
		return totalSalesCount;
	}

	/// @notice Satışların id listesini aralıkla döndürür [fromId, toId] (dahil)
	function getSalesInRange(uint256 fromId, uint256 toId) external view returns (Sale[] memory list) {
		require(toId >= fromId, "range");
		require(toId <= totalSalesCount, "oob");
		uint256 len = toId - fromId + 1;
		list = new Sale[](len);
		for (uint256 i = 0; i < len; i++) {
			list[i] = sales[fromId + i];
		}
	}

	/// @notice Tekil satış verisini döndürür (struct olarak)
	function getSaleByIndex(uint256 saleId) external view returns (Sale memory) {
		return sales[saleId];
	}

	/// @notice Kullanıcının katıldığı satışların id listesi
	function getUserSaleIds(address user) external view returns (uint256[] memory) {
		return _userSaleIds[user];
	}

	// -----------------------
	// Emergency controls
	// -----------------------

	/// @notice Factory owner can withdraw any stuck funds/tokens from a child sale (emergency)
	function emergencyWithdrawFromSale(uint256 saleId, address token, address to, uint256 amount) external onlyOwner {
		require(saleId > 0 && saleId <= totalSalesCount, "oob");
		require(to != address(0), "to=0");
		VestingSale(payable(sales[saleId].saleAddress)).emergencyWithdraw(token, to, amount);
		emit EmergencyWithdrawn(saleId, token, to, amount);
	}

	function emergencyWithdrawETHFromSale(uint256 saleId, address to, uint256 amount) external onlyOwner {
		require(saleId > 0 && saleId <= totalSalesCount, "oob");
		require(to != address(0), "to=0");
		VestingSale(payable(sales[saleId].saleAddress)).emergencyWithdrawETH(to, amount);
		emit EmergencyWithdrawn(saleId, address(0), to, amount);
	}

	// -----------------------
	// Internal: record user participation (called by child)
	// -----------------------

	function _recordUserSale(address user) external {
		// only callable by a known sale
		uint256 id = saleIdOf[msg.sender];
		require(sales[id].saleAddress == msg.sender, "sale");
		_userSaleIds[user].push(id);
	}

}

/// @dev Child contract that holds sale state and vesting/claim logic
contract VestingSale is ReentrancyGuard {
	using SafeERC20 for IERC20;
	using ECDSA for bytes32;
	using MessageHashUtils for bytes32;

	// Immutable config
	VestingSalePlatform public immutable factory;
	address public immutable projectOwner;
	address public immutable token; // token being sold
	PaymentCurrency public immutable currency;
	uint256 public startTime;
	uint256 public endTime;
	uint256 public immutable vestingDuration;
	uint256 public immutable hardCap;
	uint256 public immutable discount;

	bool public endedEarly;
	bool public proceedsWithdrawn;

	// Accumulators
	uint256 public soldTokens; // total tokens allocated to buyers
	uint256 public buyersCount;
	uint256 public totalClaimed; // total tokens claimed by all users (accurate tracking)

	// Proceeds tracked per currency
	uint256 public totalRaisedNative; // ETH
	mapping(address => uint256) public totalRaisedERC20; // token => amount

	struct BuyerData {
		uint256 amount;  // total purchased tokens
		uint256 claimed; // already claimed
		bool participated;
	}
	mapping(address => BuyerData) public buyers;

	event Bought(address indexed buyer, uint256 payAmount, uint256 tokenAmount);
	event Claimed(address indexed buyer, uint256 amount);
	event EndedEarly(uint256 when);
	event ProceedsWithdrawn(address indexed to, uint256 amountAfterFee, uint256 fee);

	// Local constants (mirror platform fee constants)
	uint256 private constant FEE_BPS_LOCAL = 100; // 1%
	uint256 private constant BPS_DENOM_LOCAL = 10_000;

	modifier onlyProjectOwner() {
		require(msg.sender == projectOwner, "owner");
		_;
	}

	constructor(
		address _factory,
		address _projectOwner,
		address _token,
		PaymentCurrency _currency,
		uint256 _startTime,
		uint256 _endTime,
		uint256 _vestingDuration,
		uint256 _hardCap,
		uint256 _discount
	) {
		require(_factory != address(0) && _projectOwner != address(0) && _token != address(0), "zero");
		factory = VestingSalePlatform(payable(_factory));
		projectOwner = _projectOwner;
		token = _token;
		currency = _currency;
		startTime = _startTime;
		endTime = _endTime;
		vestingDuration = _vestingDuration;
		hardCap = _hardCap;
		discount = _discount;
	}

	// -------------
	// Sale state
	// -------------

	function isActive() public view returns (bool) {
		return block.timestamp >= startTime && block.timestamp < endTime && !endedEarly;
	}

	function hasEnded() public view returns (bool) {
		return endedEarly || block.timestamp >= endTime;
	}

	function _maybeEndEarly() internal {
		if (!endedEarly && soldTokens >= hardCap) {
			endedEarly = true;
			endTime = block.timestamp;
			emit EndedEarly(block.timestamp);
			factory.onEndedEarly();
		}
	}

	// -------------
	// Funding
	// -------------

	// Sequential nonce tracking to prevent collision: user => next expected nonce
	mapping(address => uint256) public userNonces;

	// Buy using backend-signed quote
	// For ETH: paymentToken = address(0) and msg.value == paymentAmount
	// For ERC20: paymentToken = USDT or USD1, and amount transferred via safeTransferFrom
	// Signature covers: saleAddress, buyer, paymentToken, paymentAmount, tokensOut, deadline, nonce
	function buyWithQuote(
		address paymentToken,
		uint256 paymentAmount,
		uint256 tokensOut,
		uint256 deadline,
		uint256 nonce,
		bytes calldata signature
	) external payable nonReentrant {
		require(isActive(), "inactive");
		require(block.timestamp <= deadline, "expired");

		// Sequential nonce validation to prevent collision
		require(nonce == userNonces[msg.sender], "invalid-nonce");
		userNonces[msg.sender]++; // Increment for next transaction

		require(tokensOut > 0 && paymentAmount > 0, "zero");

		// Validate payment token according to sale currency
		if (currency == PaymentCurrency.NATIVE) {
			require(paymentToken == address(0), "native-token");
			require(msg.value == paymentAmount, "value");
			require(msg.value > 0, "zero-value"); // Additional safety check
		} else if (currency == PaymentCurrency.USDT) {
			require(paymentToken == factory.usdt(), "!usdt");
			require(msg.value == 0, "no-eth-for-usdt"); // Ensure no ETH sent
		} else if (currency == PaymentCurrency.USD1) {
			require(paymentToken == factory.usd1(), "!usd1");
			require(msg.value == 0, "no-eth-for-usd1"); // Ensure no ETH sent
		}

		// Verify signature from factory.quoteSigner
		address signer = factory.quoteSigner();
		require(signer != address(0), "no-signer");

		bytes32 digest = keccak256(
			abi.encode(
				block.chainid,        // Add chain ID to prevent cross-chain replay
				address(this),        // Contract address
				msg.sender,           // Buyer address
				paymentToken,         // Payment token address
				paymentAmount,        // Payment amount
				tokensOut,           // Tokens to receive
				deadline,            // Transaction deadline
				nonce                // Unique nonce
			)
		).toEthSignedMessageHash();
		require(digest.recover(signature) == signer, "sig");

		// Enforce cap
		require(soldTokens + tokensOut <= hardCap, "cap");

		// Record buyer
		BuyerData storage b = buyers[msg.sender];
		if (!b.participated) {
			b.participated = true;
			buyersCount += 1;
			factory._recordUserSale(msg.sender);
			factory.onFirstParticipation();
		}
		b.amount += tokensOut;
		soldTokens += tokensOut;

		// Take payment - single validation point to prevent inconsistency
		if (currency == PaymentCurrency.NATIVE) {
			// ETH payment - already validated above
			totalRaisedNative += paymentAmount; // Use paymentAmount consistently
		} else {
			// ERC20 payment
			IERC20(paymentToken).safeTransferFrom(msg.sender, address(this), paymentAmount);
			totalRaisedERC20[paymentToken] += paymentAmount;
		}

		factory.onPurchase(msg.sender, tokensOut, paymentAmount);
		emit Bought(msg.sender, paymentAmount, tokensOut);
		_maybeEndEarly();
	}

	// -------------
	// Claims (linear vesting)
	// -------------

	function vestingStart() public view returns (uint256) {
		return hasEnded() ? endTime : 0;
	}

	function vestedAmount(address user) public view returns (uint256) {
		BuyerData memory b = buyers[user];
		if (b.amount == 0) return 0;
		uint256 vs = vestingStart();
		if (vs == 0) return 0; // not started
		if (block.timestamp <= vs) return 0;
		if (vestingDuration == 0) return b.amount; // safety

		// Use precise time-based vesting instead of daily chunks to avoid precision loss
		uint256 elapsed = block.timestamp - vs;
		if (elapsed >= vestingDuration) return b.amount; // fully vested

		// Calculate vested amount with full precision: (amount * elapsed) / totalDuration
		// This eliminates precision loss from daily rounding
		return (b.amount * elapsed) / vestingDuration;
	}

	function claimable(address user) public view returns (uint256) {
		BuyerData memory b = buyers[user];
		uint256 v = vestedAmount(user);
		if (v <= b.claimed) return 0;
		return v - b.claimed;
	}

	function claim() external nonReentrant {
		uint256 amount = claimable(msg.sender);
		require(amount > 0, "no-claim");
		buyers[msg.sender].claimed += amount;
		totalClaimed += amount; // Accurate global tracking
		IERC20(token).safeTransfer(msg.sender, amount);
		factory.onClaim(msg.sender, amount);
		emit Claimed(msg.sender, amount);
	}

	// -------------
	// Project withdrawals
	// -------------

	/// @notice Project owner withdraws raised funds after sale ended
	function withdrawProceeds() external nonReentrant onlyProjectOwner {
		require(hasEnded(), "not-ended");
		require(!proceedsWithdrawn, "done");
		proceedsWithdrawn = true;

		address treasury = factory.treasury();

		if (currency == PaymentCurrency.NATIVE) {
			uint256 bal = address(this).balance;
			uint256 fee = (bal * FEE_BPS_LOCAL) / BPS_DENOM_LOCAL;
			uint256 net = bal - fee;
			if (fee > 0) {
				(bool ok1, ) = payable(treasury).call{value: fee}("");
				require(ok1, "fee-xfer");
			}
			(bool ok2, ) = payable(projectOwner).call{value: net}("");
			require(ok2, "net-xfer");
			factory.onProceedsWithdraw(net, fee);
			emit ProceedsWithdrawn(projectOwner, net, fee);
		} else {
			address payment = currency == PaymentCurrency.USDT ? factory.usdt() : factory.usd1();
			uint256 bal = IERC20(payment).balanceOf(address(this));
			uint256 fee = (bal * FEE_BPS_LOCAL) / BPS_DENOM_LOCAL;
			uint256 net = bal - fee;
			if (fee > 0) IERC20(payment).safeTransfer(treasury, fee);
			IERC20(payment).safeTransfer(projectOwner, net);
			factory.onProceedsWithdraw(net, fee);
			emit ProceedsWithdrawn(projectOwner, net, fee);
		}
	}

	/// @notice Project owner can withdraw remaining unsold tokens after sale ended
	function withdrawUnsoldTokens(address to) external onlyProjectOwner {
		require(hasEnded(), "not-ended");
		require(to != address(0), "to=0");

		uint256 bal = IERC20(token).balanceOf(address(this));
		uint256 neededForUnclaimed = soldTokens - totalClaimed; // Use accurate totalClaimed
		require(bal > neededForUnclaimed, "none");

		uint256 excess = bal - neededForUnclaimed;
		require(excess > 0, "no-excess");

		IERC20(token).safeTransfer(to, excess);
	}

	/// @notice Get total tokens that need to remain in contract for unclaimed vesting
	function getRequiredTokenBalance() external view returns (uint256) {
		return soldTokens - totalClaimed;
	}

	// -------------
	// Emergency controls (factory owner)
	// -------------

	function emergencyWithdraw(address erc20, address to, uint256 amount) external {
		require(msg.sender == address(factory), "factory-only");
		require(to != address(0), "to=0");
		IERC20(erc20).safeTransfer(to, amount);
	}

	function emergencyWithdrawETH(address to, uint256 amount) external {
		require(msg.sender == address(factory), "factory-only");
		require(to != address(0), "to=0");
		(bool ok, ) = payable(to).call{value: amount}("");
		require(ok, "eth-xfer");
	}

	// -------------
	// Views for UI convenience
	// -------------

	function getBuyerInfo(address user) external view returns (PurchaseInfo memory info, uint256 pending) {
		BuyerData memory b = buyers[user];
		info = PurchaseInfo({
			saleAddress: address(this),
			amount: b.amount,
			claimed: b.claimed,
			participated: b.participated
		});
		uint256 c = claimable(user);
		return (info, c);
	}

	receive() external payable {}
	fallback() external payable {}
}

